    private function syncIdSequence(string $table): void
    {
        $max = (int) DB::table($table)->max('id');

        if ($max < 1) {
            return;
        }

        match (DB::getDriverName()) {
            'pgsql' => DB::statement("SELECT setval(pg_get_serial_sequence('{$table}', 'id'), {$max})"),
            'mysql' => DB::statement('ALTER TABLE '.$table.' AUTO_INCREMENT = '.($max + 1)),
            'sqlite' => DB::table('sqlite_sequence')->where('name', $table)->update(['seq' => $max]),
            default => null,
        };
    }
